critique.content:
{
  "requires_refine": true,
  "issues": [
    {
      "category": "consistency",
      "description": "The translation fails to follow the provided terminology constraints: 'page-fault' and 'page fault' should be translated as 'fallo de página' instead of keeping the English term or using a hybrid."
    },
    {
      "category": "consistency",
      "description": "The translation uses 'flag' and 'bits de permiso' instead of the standard technical Spanish 'bit' or 'permisos' as implied by the context of PTEs, and it fails to translate 'load page faults', 'store page faults', and 'instruction page faults' which should be 'fallos de página de carga/almacenamiento/instrucción'."
    },
    {
      "category": "fluency",
      "description": "The phrase 'la obtención de instrucciones para ser ejecutadas' is a bit clunky; 'la búsqueda de instrucciones' or 'la carga de instrucciones' would be more idiomatic for 'fetches'."
    }
  ]
}

